'use strict';
// Franklin Ace 1000 system ROM (6x 2K chips, $D000-$FFFF) and the Disk II
// 16-sector boot PROM (341-0027, $C600-$C6FF, slot 6), plus the default boot
// disk image (DOS 3.3 order, 35 tracks x 16 sectors x 256 bytes), all base64.
//
// The system ROM chips and boot disk are dumps of the user's own Franklin Ace
// 1000 hardware/media. The Disk II boot PROM is not part of that dump (it lives
// on a separate disk controller card) -- its bytes here are the well-known,
// widely-published 16-sector boot PROM, byte-for-byte verified against this
// exact ROM set: the Autostart Monitor's bootable-card signature check (bytes
// at $Cn01/$Cn03/$Cn05/$Cn07 must read $20/$00/$03/$3C) was disassembled directly
// out of the real F8 chip and matches exactly.
const ROM_DATA = {
  d0: "",
  d8: "",
  e0: "",
  e8: "",
  f0: "",
  f8: "",
  disk2boot: "",
};

const DEFAULT_BOOT_DISK_B64 = "";

function b64ToBytes(b64) {
  const bin = atob(b64);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}

// Returns a Uint8Array(0x3000) covering $D000-$FFFF.
function decodeSystemRom() {
  const rom = new Uint8Array(0x3000);
  const chips = [ROM_DATA.d0, ROM_DATA.d8, ROM_DATA.e0, ROM_DATA.e8, ROM_DATA.f0, ROM_DATA.f8];
  let offset = 0;
  for (const chip of chips) {
    const bytes = b64ToBytes(chip);
    rom.set(bytes, offset);
    offset += bytes.length;
  }
  return rom;
}

// Returns a Uint8Array(256) -- the Disk II boot PROM for $C600-$C6FF.
function decodeDisk2BootRom() {
  return b64ToBytes(ROM_DATA.disk2boot);
}

// Returns a Uint8Array(35*16*256) -- the default boot disk, DOS 3.3 order.
function decodeDefaultBootDisk() {
  return b64ToBytes(DEFAULT_BOOT_DISK_B64);
}

